@jiyuuchc I think the problem is you made a typo? This code works just fine.
```python
import jax.numpy as jnp
import jax.tree_util as tu
from jax import Array, jit


@tu.register_pytree_node_class
class A:
  initial_value: Array
  updated_value: Array

  def __init__(self, initial_value: Array, updated_value: Array):
    self.initial_value = initial_value
    self.updated_value = updated_value
    #         ^^------ should have been self.updated_value

  @classmethod 
  def init(cls, initial_value: Array):
    return cls(initial_value, initial_value)

  def update(self):
    self.updated_value += 10

  def reset(self):
    self.updated_value = self.initial_value

  def tree_flatten(self):
    return (self.initial_value, self.updated_value), None

  @classmethod
  def tree_unflatten(cls, _, children):
    return cls(*children)

a = A.init(jnp.arange(10))

def f(a: A):
  a.update()
  a.reset()
  a.update()
  return a

jit(f, donate_argnums=(0,))(a).updated_value
```

